package mod

import (
	"time"
)

type Module struct {
	Path     string     `json:"Path"`
	Version  string     `json:"Version"`
	Time     *time.Time `json:"Time"`
	Update   *Module    `json:"Update"`
	Main     bool       `json:"Main"`
	Indirect bool       `json:"Indirect"`
	Replace  *Module    `json:"Replace"`
}

func (m *Module) InvalidTimestamp() bool {
	if m.Time == nil || m.Update == nil || m.Update.Time == nil {
		return false
	}
	return m.Time.After(*m.Update.Time)
}
EOF

cat << 'EOF' > internal/runner/runner.go
package runner

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"strconv"
	"strings"

	"github.com/psampaz/go-mod-outdated/internal/mod"
)

func Run(r io.Reader, w io.Writer, update bool, direct bool, ci bool, style string) error {
	var modules []mod.Module
	decoder := json.NewDecoder(r)

	for {
		var m mod.Module
		if err := decoder.Decode(&m); err != nil {
			if err == io.EOF {
				break
			}
			log.Println(err)
			return nil
		}

		if m.Main {
			continue
		}

		if m.Replace != nil {
			m.Version = m.Replace.Version
			m.Time = m.Replace.Time
			m.Update = m.Replace.Update
		}

		if direct && m.Indirect {
			continue
		}

		if update && m.Update == nil {
			continue
		}

		modules = append(modules, m)
	}

	if len(modules) == 0 {
		return nil
	}

	renderTable(w, modules, style)

	if ci {
		for _, m := range modules {
			if m.Update != nil {
				return errors.New("outdated dependencies found")
			}
		}
	}

	return nil
