		if update && m.Update == nil {
			continue
		}

		modules = append(modules, m)
	}

	if len(modules) == 0 {
		return nil
	}

	renderTable(w, modules, style)

	if ci {
		for _, m := range modules {
			if m.Update != nil {
				return errors.New("outdated dependencies found")
			}
		}
	}

	return nil
}

func renderTable(w io.Writer, modules []mod.Module, style string) {
	headers := []string{"MODULE", "VERSION", "NEW VERSION", "DIRECT", "VALID TIMESTAMPS"}
	rows := make([][]string, len(modules))

	for i, m := range modules {
		newVersion := ""
		if m.Update != nil {
			newVersion = m.Update.Version
		}
		rows[i] = []string{
			m.Path,
			m.Version,
			newVersion,
			strconv.FormatBool(!m.Indirect),
			strconv.FormatBool(!m.InvalidTimestamp()),
		}
	}

	colWidths := make([]int, len(headers))
	for i, h := range headers {
		colWidths[i] = utf8.RuneCountInString(h)
	}
	for _, row := range rows {
		for i, val := range row {
			rc := utf8.RuneCountInString(val)
			if rc > colWidths[i] {
				colWidths[i] = rc
			}
		}
	}

	makeBorder := func(sep, fill string) string {
		parts := make([]string, len(headers))
		for i, w := range colWidths {
			parts[i] = strings.Repeat(fill, w+2)
		}
		return sep + strings.Join(parts, sep) + sep
	}

	makeHeaderRow := func() string {
		parts := make([]string, len(headers))
		for i, h := range headers {
			w := colWidths[i]
			extra := w - utf8.RuneCountInString(h)
			left := 1 + extra/2
			right := 1 + extra - extra/2
			parts[i] = strings.Repeat(" ", left) + h + strings.Repeat(" ", right)
		}
		return "|" + strings.Join(parts, "|") + "|"
	}

	makeDataRow := func(row []string) string {
		parts := make([]string, len(headers))
		for i, val := range row {
			w := colWidths[i]
			right := 1 + (w - utf8.RuneCountInString(val))
			parts[i] = " " + val + strings.Repeat(" ", right)
		}
		return "|" + strings.Join(parts, "|") + "|"
	}

	if style == "markdown" {
		fmt.Fprintln(w, makeHeaderRow())
		fmt.Fprintln(w, makeBorder("|", "-"))
		for _, row := range rows {
			fmt.Fprintln(w, makeDataRow(row))
		}
	} else {
		topBorder := makeBorder("+", "-")
		fmt.Fprintln(w, topBorder)
		fmt.Fprintln(w, makeHeaderRow())
		fmt.Fprintln(w, topBorder)
		for _, row := range rows {
			fmt.Fprintln(w, makeDataRow(row))
		}
		fmt.Fprintln(w, topBorder)
	}
}
